content:
body {
  margin: 0;
  padding: 0;
  font-family: system-ui, -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Oxygen, Ubuntu, Cantarell, 'Open Sans', 'Helvetica Neue', sans-serif;
  background-color: #0f172a;
  color: #f8fafc;
  display: flex;
  justify-content: center;
  align-items: center;
  min-height: 100vh;
}

.app-container {
  display: flex;
  flex-direction: column;
  align-items: center;
  width: 100%;
  max-width: 600px;
  padding: 2rem;
  box-sizing: border-box;
  background: rgba(30, 41, 59, 0.7);
  backdrop-filter: blur(10px);
  border-radius: 1rem;
  box-shadow: 0 10px 25px -5px rgba(0, 0, 0, 0.3), 0 8px 10px -6px rgba(0, 0, 0, 0.3);
  border: 1px solid rgba(255, 255, 255, 0.1);
}

.header {
  text-align: center;
  margin-bottom: 1.5rem;
}

.title {
  font-size: 1.8rem;
  font-weight: 700;
  margin: 0 0 0.5rem 0;
  background: linear-gradient(to right, #38bdf8, #818cf8);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
}

.instruction {
  font-size: 0.95rem;
  color: #94a3b8;
  margin: 0;
}

.canvas-container {
  width: 100%;
  height: 350px;
  border-radius: 0.75rem;
  overflow: hidden;
  background: #020617;
  box-shadow: inset 0 2px 4px 0 rgba(0, 0, 0, 0.6);
  margin-bottom: 1.5rem;
  cursor: grab;
}

.canvas-container:active {
  cursor: grabbing;
}

.btn {
  background: linear-gradient(135deg, #3b82f6 0%, #6366f1 100%);
  color: white;
  border: none;
  padding: 0.75rem 1.5rem;
  font-size: 1rem;
  font-weight: 600;
  border-radius: 0.5rem;
  cursor: pointer;
  transition: all 0.2s ease;
  box-shadow: 0 4px 6px -1px rgba(59, 130, 246, 0.4);
}

.btn:hover {
  filter: brightness(1.1);
  transform: translateY(-1px);
  box-shadow: 0 6px 8px -1px rgba(59, 130, 246, 0.5);
}

.btn:active {
  transform: translateY(0);
  box-shadow: 0 2px 4px -1px rgba(59, 130, 246, 0.4);
}

import { useEffect, useRef } from 'react'
import * as THREE from 'three'
import './index.css'

interface Cube3DProps {
  cubeColor?: string
}

export default function Cube3D({ cubeColor = '#3b82f6' }: Cube3DProps) {
  const mountRef = useRef<HTMLDivElement>(null)
  const cubeRef = useRef<THREE.Mesh | null>(null)

  useEffect(() => {
    const currentMount = mountRef.current
    if (!currentMount) return

    const scene = new THREE.Scene()
    const camera = new THREE.PerspectiveCamera(
      75,
      currentMount.clientWidth / currentMount.clientHeight,
      0.1,
      1000
    )
    camera.position.z = 3

    const renderer = new THREE.WebGLRenderer({ antialias: true, alpha: true })
    renderer.setSize(currentMount.clientWidth, currentMount.clientHeight)
    renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2))
    currentMount.appendChild(renderer.domElement)

    const ambientLight = new THREE.AmbientLight(0xffffff, 0.7)
    scene.add(ambientLight)

    const pointLight = new THREE.PointLight(0xffffff, 1)
    pointLight.position.set(5, 5, 5)
    scene.add(pointLight)

    const geometry = new THREE.BoxGeometry(1.5, 1.5, 1.5)
    const material = new THREE.MeshStandardMaterial({
      color: cubeColor,
      roughness: 0.3,
      metalness: 0.2,
    })
    const cube = new THREE.Mesh(geometry, material)
    scene.add(cube)
    cubeRef.current = cube

    let animationFrameId: number
    let isDragging = false
    let previousMousePosition = { x: 0, y: 0 }

    const animate = () => {
      animationFrameId = requestAnimationFrame(animate)
      if (!isDragging && cubeRef.current) {
        cubeRef.current.rotation.x += 0.005
        cubeRef.current.rotation.y += 0.007
      }
      renderer.render(scene, camera)
    }
    animate()

    const handlePointerDown = (e: PointerEvent) => {
      isDragging = true
      previousMousePosition = { x: e.clientX, y: e.clientY }
    }

    const handlePointerMove = (e: PointerEvent) => {
      if (!isDragging || !cubeRef.current) return

      const deltaX = e.clientX - previousMousePosition.x
      const deltaY = e.clientY - previousMousePosition.y

      cubeRef.current.rotation.y += deltaX * 0.01
      cubeRef.current.rotation.x += deltaY * 0.01

      previousMousePosition = { x: e.clientX, y: e.clientY }
    }

    const handlePointerUp = () => {
      isDragging = false
    }

    currentMount.addEventListener('pointerdown', handlePointerDown)
    window.addEventListener('pointermove', handlePointerMove)
    window.addEventListener('pointerup', handlePointerUp)

    const handleResize = () => {
      if (!currentMount) return
      camera.aspect = currentMount.clientWidth / currentMount.clientHeight
      camera.updateProjectionMatrix()
      renderer.setSize(currentMount.clientWidth, currentMount.clientHeight)
    }
    window.addEventListener('resize', handleResize)

    return () => {
      window.removeEventListener('resize', handleResize)
      currentMount.removeEventListener('pointerdown', handlePointerDown)
      window.removeEventListener('pointermove', handlePointerMove)
      window.removeEventListener('pointerup', handlePointerUp)
      cancelAnimationFrame(animationFrameId)
      if (renderer.domElement && currentMount.contains(renderer.domElement)) {
        currentMount.removeChild(renderer.domElement)
      }
      geometry.dispose()
      material.dispose()
      renderer.dispose()
    }
  }, [cubeColor])

  return <div ref={mountRef} className="canvas-container" />
}

import { useState } from 'react'
import Cube3D from './Cube3D'
import './index.css'

export default function App() {
  const colors = ['#3b82f6', '#ec4899', '#10b981', '#f59e0b', '#8b5cf6']
  const [colorIndex, setColorIndex] = useState(0)

  const handleChangeColor = () => {
    setColorIndex((prev) => (prev + 1) % colors.length)
  }

  return (
    <div className="app-container">
      <header className="header">
        <h1 className="title">3D 立方体ビューアー</h1>
        <p className="instruction">マウスまたはタッチで立方体をドラッグして回転させよう</p>
      </header>

      <Cube3D cubeColor={colors[colorIndex]} />

      <button className="btn" onClick={handleChangeColor}>
        色を変更する
      </button>
    </div>
  )
}
